test("approvers scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "proof-threshold", "1.00");
  expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.04", "note": ""})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  await ui.setSetting(pg_uma, "fiscal-start-month", "7");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-10", "half-up")).toBe(true);
  await ui.setSetting(pg_uma, "review-threshold", "1.50");
  await ui.setSetting(pg_uma, "review-sla", "5");
  await ui.setSetting(pg_uma, "escalate-after", "1");
  await ui.setSetting(pg_uma, "proof-kinds", "receipt,photo");
  await ui.setSetting(pg_uma, "default-grade", "C");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00", "from": "2026-03-16"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "contact": " Ada@x ", "tags": "a"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "20"})).toBeNull();
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "20", "termsFrom": "2026-03-01"})).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "");
  expect(await ui.setApprover(pg_uma, p_ben, "vic")).toBe(true);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-09", "to": "2026-03-20"})).toBe(true);
  expect(await ui.exportCsv(pg_uma)).toBe("name,grade,retired-from,due-total\nCam,A,,0.00\nBen,A,,0.00\n");
  await ui.setToday(pg_uma, "2026-03-31");
  expect(await ui.bulkRetire(pg_uma, [p_ben, p_cam], "2026-02-10")).toBe(2);
  await ui.showRetired(pg_uma, true);
  expect(await ui.editPerson(pg_uma, p_ben, {"grade": "A"})).toBe(true);
  await ui.refresh(pg_uma);
  expect(await ui.watch(pg_uma, p_cam, true)).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "soft-close")).toBe(true);
  expect(await ui.addPatron(pg_uma, p_cam, "Ben")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.statementAsOf(pg_uma, p_ben, "2026-03-01")).toBe(false);
  expect(await ui.importOpenings(pg_uma, "Cam,P1,x")).toBeNull();
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-16", "to": "2026-03-12"})).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.addAlias(pg_uma, p_ben, "Bee")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  await ui.refresh(pg_uma);

